/// if we are attacking "fromID", stop that and attack "toID" instead
// ?transferAttack@AIUpdateInterface@@QAEXW4ObjectID@@0@Z
void AIUpdateInterface::transferAttack(ObjectID fromID, ObjectID toID)
{
	BFMEAIUpdateFields *self = reinterpret_cast<BFMEAIUpdateFields *>(this);

	if (self->m_currentVictimID == fromID)
		self->m_currentVictimID = toID;

	// The replacement is looked up only when it is needed, and BFME transfers
	// no turret targets here.
	Object *goalObj = self->m_stateMachine->getGoalObject();
	if (goalObj && goalObj->getID() == fromID)
	{
		BFMEGoalObjectMachine *stateMachine =
			reinterpret_cast<BFMEGoalObjectMachine *>( self->m_stateMachine );
		stateMachine->setGoalObject(
			reinterpret_cast<BFMEObjectLookup *>(TheGameLogic)->findObjectByID( toID ) );
	}
}

//----------------------------------------------------------------------------------------------------------
/**
 * Indicate who we are attacking.
 */
// ?setCurrentVictim@AIUpdateInterface@@QAEXPBVObject@@@Z
void AIUpdateInterface::setCurrentVictim( const Object *victim )
{
	BFMEAIUpdateFields *fields = reinterpret_cast<BFMEAIUpdateFields *>(this);

	if (victim == NULL)
	{
		// be paranoid, in case we are called from dtors, etc.
		if (fields->m_currentVictimID != INVALID_ID)
		{
			Object* self = fields->getObject();
			Object* target = reinterpret_cast<BFMEObjectLookup *>(TheGameLogic)->findObjectByID(
				fields->m_currentVictimID );
			if (self != NULL && target != NULL)
			{
				BFMEAddTargeterAI* targetAI =
					reinterpret_cast<const BFMEObjectAIField *>(target)->getAI();
				if (targetAI)
				{
					targetAI->addTargeter(self->getID(), FALSE);
				}
			}
		}

		fields->m_currentVictimID = INVALID_ID;
	}
	else
	{
		// we don't add a targeter here, since we usually want to defer
		// that until we are actually aiming (as opposed to, say, approaching)
		// the victim.
		fields->m_currentVictimID = victim->getID();
	}
}

/**
 * Who is our current victim?
 */
// ?getCurrentVictim@AIUpdateInterface@@QBEPAVObject@@XZ
Object *AIUpdateInterface::getCurrentVictim( void ) const
{
	const BFMEAIUpdateFields *self = reinterpret_cast<const BFMEAIUpdateFields *>(this);

	if (self->m_currentVictimID != INVALID_ID)
		return reinterpret_cast<BFMEObjectLookup *>(TheGameLogic)->findObjectByID(
			self->m_currentVictimID );

	return NULL;
}

// if we are attacking a position (and NOT an object), return it. otherwise return null.
// ?getCurrentVictimPos@AIUpdateInterface@@QBEPBUCoord3D@@XZ
const Coord3D *AIUpdateInterface::getCurrentVictimPos( void ) const
{
	const BFMEAIUpdateFields *self = reinterpret_cast<const BFMEAIUpdateFields *>(this);

	// The status word is read in place: testStatus is not called.
	if (reinterpret_cast<const BFMEObjectStatusWord *>(self->m_object)->m_status & 0x00400000)
	{
		if (self->m_currentVictimID == INVALID_ID)
		{
			return &reinterpret_cast<const BFMEStateMachineFields *>(self->m_stateMachine)->m_goalPosition;
		}
	}

	return NULL;
}


