{
	DOOR_1 = 0,
	DOOR_2 = 1,
	DOOR_3 = 2,
	DOOR_4 = 3,

	DOOR_COUNT_MAX = 4,

	DOOR_NONE_AVAILABLE = -1,	// need a door, but none currently available
	DOOR_NONE_NEEDED		= -2	// don't need a door reservation
};

